import re
import datetime
from typing import Any


def od_rows(type_slug: str, q: str = "") -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    cursor: str | None = None
    for _ in range(100):
        if q:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor, q=q)
        else:
            page = api.records.list(type_slug=type_slug, limit=200, cursor=cursor)
        out.extend(page.get("records") or [])
        cursor = page.get("nextCursor")
        if not cursor:
            break
    return out


def od_data(row: Any) -> dict[str, Any]:
    return dict((row or {}).get("data") or {})


def od_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""


def od_link_ids(row: Any, field: str) -> list[str]:
    out: list[str] = []
    for ref in ((row or {}).get("links") or {}).get(field) or []:
        if isinstance(ref, dict) and ref.get("id"):
            out.append(str(ref["id"]))
        elif isinstance(ref, str):
            out.append(ref)
    return out


def od_order_lines(order_id: str, order_number: str) -> list[dict[str, Any]]:
    found = [r for r in od_rows("od_order_lines", order_number) if order_id in od_link_ids(r, "order")]
    if not found:
        found = [r for r in od_rows("od_order_lines") if order_id in od_link_ids(r, "order")]
    found.sort(key=lambda r: float(od_data(r).get("line_number") or 0))
    return found


def od_now() -> str:
    return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()


def od_send_sales_order(order_id: str, handover: dict[str, Any], customer_name: str) -> str:
    number = "SO-" + od_text(handover.get("order_number"))
    text_lines: list[str] = []
    for x in handover.get("lines") or []:
        row = od_text(x.get("item_code")) + "  x " + od_text(x.get("quantity")) + " " + od_text(x.get("unit"))
        if od_text(x.get("note")):
            row += "  (" + od_text(x.get("note")) + ")"
        text_lines.append(row.strip())
    data: dict[str, Any] = {
        "account_code": od_text(handover.get("account_code"))[:80],
        "customer_name": customer_name[:300],
        "po_number": od_text(handover.get("po_number"))[:120],
        "delivery_address": od_text(handover.get("delivery_address"))[:1000],
        "line_count": len(text_lines),
        "lines": "\n".join(text_lines)[:20000],
        "sent_on": od_now(),
    }
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", od_text(handover.get("delivery_date"))[:10]):
        data["delivery_date"] = od_text(handover.get("delivery_date"))[:10]
    record: dict[str, Any] = {"title": number, "data": data, "links": {"order": [order_id]}}
    same = [r for r in od_rows("od_sales_orders", number) if od_text(r.get("title")) == number]
    if same:
        api.records.update(type_slug="od_sales_orders", record_id=same[0]["id"], record=record)
    else:
        api.records.create(type_slug="od_sales_orders", record=record)
    return number


